// cfgWith builds a context config holding the given agent_usage YAML.
func cfgWith(t *testing.T, agentUsageYAML string) *config.Config {
	t.Helper()
	cfg := config.Default()
	if agentUsageYAML == "" {
		return cfg
	}
	if err := yaml.Unmarshal([]byte(agentUsageYAML), &cfg.AgentUsage); err != nil {
