// The numbers below are the plan's H8, to be confirmed against the real layout
// (they come from this test's first green run, not from a measurement made
// before the column existed): Est. cost is the last optional column to go.
func TestEstCostLayoutAtEachWidth(t *testing.T) {
	tests := []struct {
		width int
		want  []string
	}{
		{200, []string{"Agent", "ID", costTitle, "State", "Tools", "Duration", "Model", "In", "Out", "Cache read", "Cache write", "Total", "Share"}},
		{100, []string{"Agent", "ID", costTitle, "State", "Tools", "Duration", "Out", "Total", "Share"}}, // loses Model
		{80, []string{"Agent", "ID", costTitle, "State", "Tools", "Out", "Total", "Share"}},               // loses Duration
		{60, []string{"Agent", "ID", "Out", "Total", "Share"}},                                           // the five DEVDESK-43 columns remain
	}
	for _, tt := range tests {
		for name, cfg := range map[string]*config.Config{"no prices": nil, "priced": cfgWith(t, pricesYAML[1:])} {
			t.Run(name+"/"+itoa(tt.width), func(t *testing.T) {
				m := atAgents(t, cfg, tt.width, costUsage())
				if got := m.agentTable.RenderedWidth(); got != tt.width-2 {
					t.Errorf("rendered width = %d, want %d (Rule 116)", got, tt.width-2)
				}
				got := header(t, m.View())
				if strings.Join(got, ",") != strings.Join(tt.want, ",") {
					t.Errorf("columns at %d = %v, want %v:\n%s", tt.width, got, tt.want, m.View())
				}
			})
		}
	}
}

func itoa(n int) string { return strings.TrimSpace(strings.Repeat(" ", 0) + string(rune('0'+n/100%10)) + string(rune('0'+n/10%10)) + string(rune('0'+n%10))) }

